import React, { useState, useEffect, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import SvgFlow from '../components/SvgFlow';
import { parseToGraph, codeTemplates } from '../utils/parseToGraph';

function Editor() {
  const [searchParams] = useSearchParams();
  const [code, setCode] = useState('');
  const [lang, setLang] = useState('python');
  const [graph, setGraph] = useState(null);
  const [message, setMessage] = useState('');
  const [highlightedLine, setHighlightedLine] = useState(null);
  const [selectedNode, setSelectedNode] = useState(null);
  const textareaRef = useRef(null);

  useEffect(() => {
    const langParam = searchParams.get('lang');
    if (langParam && codeTemplates[langParam]) {
      setLang(langParam);
      setCode(codeTemplates[langParam]);
    }
  }, [searchParams]);

  const handleGenerate = () => {
    if (!code.trim()) {
      setMessage('Please enter some code to generate a flowchart.');
      setGraph(null);
      return;
    }
    
    // Validate if code matches selected language
    const isValidLanguage = validateLanguage(code, lang);
    if (!isValidLanguage) {
      setMessage(`The code you entered doesn't match the selected language (${lang.toUpperCase()}). Please select the correct language or update your code.`);
      setGraph(null);
      return;
    }
    
    const g = parseToGraph(code);
    setGraph(g);
    setMessage('');
  };

  const validateLanguage = (code, selectedLang) => {
    const trimmedCode = code.trim();
    const lowerCode = code.toLowerCase();
    
    switch(selectedLang) {
      case 'python':
        // Check for Python-specific syntax
        const hasPythonSyntax = /def\s+\w+|class\s+\w+|import\s+\w+|from\s+\w+\s+import|for\s+\w+\s+in\s+|if\s+.*:|elif\s+.*:|while\s+.*:|print\(|range\(/.test(trimmedCode);
        const hasNonPythonSyntax = /\bfunction\b|\bconst\b|\blet\b|\bvar\b|console\.log|#include|System\.out\.println|<html|SELECT\s+.*\s+FROM/i.test(trimmedCode);
        return hasPythonSyntax && !hasNonPythonSyntax;
      
      case 'javascript':
        // Check for JavaScript-specific syntax
        const hasJSSyntax = /function\s+\w+|const\s+\w+|let\s+\w+|var\s+\w+|console\.log|=>|\.forEach|\.map|\.filter/.test(trimmedCode);
        const hasNonJSSyntax = /^def\s+\w+|#include|System\.out\.println|<html|SELECT\s+.*\s+FROM/i.test(trimmedCode);
        return hasJSSyntax && !hasNonJSSyntax;
      
      case 'java':
        // Check for Java-specific syntax
        const hasJavaSyntax = /class\s+\w+|public\s+(static\s+)?void|private\s+|protected\s+|System\.out\.println|import\s+java|public\s+class/.test(trimmedCode);
        const hasNonJavaSyntax = /^def\s+\w+|#include|console\.log|<html|SELECT\s+.*\s+FROM|cout\s*<</i.test(trimmedCode);
        return hasJavaSyntax && !hasNonJavaSyntax;
      
      case 'c':
        // Check for C-specific syntax
        const hasCSyntax = /#include\s*<|int\s+main|printf\(|scanf\(|void\s+\w+\(|return\s+0;|stdio\.h/.test(trimmedCode);
        const hasNonCSyntax = /^def\s+\w+|console\.log|System\.out\.println|<html|SELECT\s+.*\s+FROM|cout\s*<<|using\s+namespace/i.test(trimmedCode);
        return hasCSyntax && !hasNonCSyntax;
      
      case 'cpp':
        // Check for C++-specific syntax
        const hasCppSyntax = /#include\s*<|using\s+namespace|cout\s*<<|cin\s*>>|std::|iostream|int\s+main/.test(trimmedCode);
        const hasNonCppSyntax = /^def\s+\w+|console\.log|System\.out\.println|<html|SELECT\s+.*\s+FROM|printf\(/i.test(trimmedCode);
        return hasCppSyntax && !hasNonCppSyntax;
      
      case 'sql':
        // Check for SQL-specific syntax
        const hasSQLSyntax = /\b(SELECT|INSERT|UPDATE|DELETE|FROM|WHERE|CREATE|DROP|ALTER|TABLE|DATABASE|JOIN|GROUP\s+BY|ORDER\s+BY)\b/i.test(trimmedCode);
        const hasNonSQLSyntax = /^def\s+\w+|function\s+\w+|#include|System\.out\.println|<html|console\.log|cout\s*<</i.test(trimmedCode);
        return hasSQLSyntax && !hasNonSQLSyntax;
      
      case 'html':
        // Check for HTML-specific syntax
        const hasHTMLSyntax = /<(!DOCTYPE\s+)?html|<head|<body|<div|<p|<h[1-6]|<style|<script|<title|<meta/i.test(trimmedCode);
        const hasNonHTMLSyntax = /^def\s+\w+|function\s+\w+(?!\s*\()|#include|System\.out\.println|SELECT\s+.*\s+FROM|console\.log(?!.*<)/i.test(trimmedCode);
        return hasHTMLSyntax && !hasNonHTMLSyntax;
      
      default:
        return true;
    }
  };

  const handleNodeClick = (lineNumber, node) => {
    if (!textareaRef.current) return;
    
    // Set the highlighted line
    setHighlightedLine(lineNumber);
    
    // Set the selected node for explanation
    setSelectedNode(node);
    
    // Scroll to the line in the textarea
    const lines = code.split('\n');
    const linesBefore = lines.slice(0, lineNumber - 1).join('\n');
    const charPosition = linesBefore.length + (lineNumber > 1 ? 1 : 0);
    
    // Move cursor to the line
    textareaRef.current.focus();
    textareaRef.current.setSelectionRange(charPosition, charPosition + lines[lineNumber - 1]?.length || 0);
    
    // Clear highlight after 2 seconds
    setTimeout(() => {
      setHighlightedLine(null);
    }, 2000);
  };

  const getNodeExplanation = (node) => {
    if (!node) return '';
    
    const nodeType = node.type || node.shape;
    const nodeText = (node.text || node.label || '').toLowerCase();
    
    // Get all nodes up to current node to understand context
    const nodeIndex = graph?.nodes?.findIndex(n => n.id === node.id) || 0;
    const previousNodes = graph?.nodes?.slice(0, nodeIndex) || [];
    const hasInput = previousNodes.some(n => n.type === 'input');
    const hasDecision = previousNodes.some(n => n.type === 'decision');
    const hasLoop = previousNodes.some(n => n.type === 'loop');
    
    let explanation = '';
    
    // Check if this is the End node
    if (nodeText.includes('end')) {
      // Generate summary of what the program did
      explanation = '🔴 **End of Program**\n\n';
      
      // Analyze the actual code to create a meaningful summary
      if (code && graph && graph.nodes) {
        const codeLines = code.toLowerCase();
        
        // Provide a natural language explanation based on code patterns
        if (codeLines.includes('even') && codeLines.includes('odd')) {
          explanation += '**What this program does:**\n\nThis program helps you find out if a number is even or odd.\n\nFirst, it creates a function that takes any number you give it. Then it divides that number by 2. If there\'s no remainder (the division is exact), it tells you the number is "Even". If there\'s a remainder left over, it tells you the number is "Odd".\n\nFinally, it tests this function by running it 5 times with different numbers to show you how it works!';
        } else if ((codeLines.includes('sum') || codeLines.includes('total') || codeLines.includes('add')) && codeLines.includes('loop')) {
          explanation += '**What this program does:**\n\nThis program adds up a series of numbers.\n\nIt starts with zero and then keeps adding numbers one by one in a loop. Each time through the loop, it adds the next number to the running total. When the loop finishes, it shows you the final sum of all the numbers.';
        } else if (codeLines.includes('factorial')) {
          explanation += '**What this program does:**\n\nThis program calculates the factorial of a number.\n\nIt takes a number and multiplies it by every smaller positive number down to 1. For example, factorial of 5 is 5 × 4 × 3 × 2 × 1 = 120. It uses a loop to do this multiplication step by step.';
        } else if (codeLines.includes('fibonacci')) {
          explanation += '**What this program does:**\n\nThis program generates the Fibonacci sequence.\n\nIt starts with 0 and 1, then keeps adding the last two numbers to get the next one. So you get: 0, 1, 1, 2, 3, 5, 8, and so on. The program repeats this process to create as many Fibonacci numbers as you want.';
        } else if (codeLines.includes('prime')) {
          explanation += '**What this program does:**\n\nThis program checks if a number is prime.\n\nA prime number can only be divided evenly by 1 and itself. The program tests this by trying to divide the number by other numbers. If none of them divide evenly, it\'s prime! Otherwise, it\'s not.';
        } else if (codeLines.includes('sort') || codeLines.includes('bubble') || codeLines.includes('arrange')) {
          explanation += '**What this program does:**\n\nThis program sorts a list of items in order.\n\nIt compares items two at a time and swaps them if they\'re in the wrong order. It keeps doing this over and over until everything is arranged correctly, from smallest to largest (or alphabetically).';
        } else if (codeLines.includes('search') || codeLines.includes('find')) {
          explanation += '**What this program does:**\n\nThis program searches for a specific item in a list.\n\nIt goes through the list one item at a time, comparing each one with what you\'re looking for. When it finds a match, it tells you where it found it. If it doesn\'t find it anywhere, it lets you know it\'s not in the list.';
        } else if (codeLines.includes('reverse')) {
          explanation += '**What this program does:**\n\nThis program reverses something.\n\nIt takes the items (could be letters in a word or numbers in a list) and flips their order completely. The first becomes last, the last becomes first, and everything in between gets flipped around too.';
        } else if (codeLines.includes('max') || codeLines.includes('min') || codeLines.includes('largest') || codeLines.includes('smallest')) {
          explanation += '**What this program does:**\n\nThis program finds the biggest or smallest number in a group.\n\nIt starts by assuming the first number is the biggest (or smallest), then checks all the other numbers one by one. Whenever it finds a bigger (or smaller) one, it remembers that instead. At the end, it tells you which number was the winner!';
        } else if (codeLines.includes('average') || codeLines.includes('mean')) {
          explanation += '**What this program does:**\n\nThis program calculates the average of a group of numbers.\n\nIt adds all the numbers together to get the total sum, then divides that sum by how many numbers there were. This gives you the "middle" value - the average!';
        } else {
          // Generic explanation based on structure
          const hasLoop = graph.nodes.some(n => n.type === 'loop');
          const hasDecision = graph.nodes.some(n => n.type === 'decision');
          const hasOutput = graph.nodes.some(n => n.type === 'output');
          
          explanation += '**What this program does:**\n\n';
          
          if (hasLoop && hasDecision) {
            explanation += 'This program processes information by repeating steps multiple times. During each repetition, it checks certain conditions to decide what to do. Based on these decisions, it performs different actions and shows you the results.';
          } else if (hasDecision) {
            explanation += 'This program makes decisions based on the information it receives. It checks if certain conditions are true or false, then does different things depending on the result. Finally, it shows you the outcome.';
          } else if (hasLoop) {
            explanation += 'This program repeats a task several times. Each time it goes through the loop, it does the same set of actions with possibly different data. When it\'s done repeating, it shows you the results.';
          } else if (hasOutput) {
            explanation += 'This program takes some input, processes it step by step following specific instructions, and then displays the final result to you.';
          } else {
            explanation += 'This program follows a series of steps to process data and complete its task.';
          }
        }
      } else {
        explanation += '**What this program does:**\n\nThe program has successfully completed all its tasks!';
      }
      
      if (node.lineNumber) {
        explanation += `\n\n📍 **Line ${node.lineNumber}** in your code`;
      }
      
      return explanation;
    }
    
    // Check if this is the Start node
    if (nodeText.includes('start')) {
      explanation = '🟢 **Start of Program**\n\nThis is where the program begins running.\n\nAll the steps below this will happen one by one.';
      
      if (node.lineNumber) {
        explanation += `\n\n📍 **Line ${node.lineNumber}** in your code`;
      }
      
      return explanation;
    }
    
    // Handle other node types
    switch(nodeType) {
      case 'input':
        const inputText = node.text || node.label || '';
        explanation = `🔵 **Getting Information**\n\n`;
        
        // Analyze what kind of input this is
        if (inputText.toLowerCase().includes('param') || inputText.toLowerCase().includes('argument')) {
          explanation += `**What's happening:** The function is receiving parameters (inputs) that were passed to it.\n\n`;
          explanation += `Think of parameters like ingredients you give to a recipe. The function needs these to do its work. In this case, the parameters are: **${inputText}**\n\n`;
          explanation += `These values will be used in the steps below to calculate the result.`;
        } else if (inputText.toLowerCase().includes('input') || inputText.toLowerCase().includes('read')) {
          explanation += `**What's happening:** The program is asking the user to provide some information.\n\n`;
          explanation += `Just like when a form asks you to fill in your name or age, this program is waiting for you to enter: **${inputText}**\n\n`;
          explanation += `Whatever you type will be stored and used in the following steps.`;
        } else if (inputText.toLowerCase().includes('file') || inputText.toLowerCase().includes('open')) {
          explanation += `**What's happening:** The program is reading data from a file.\n\n`;
          explanation += `**Action:** ${inputText}\n\n`;
          explanation += `This data will be loaded into memory so the program can work with it.`;
        } else {
          explanation += `**What's happening:** The program is getting some data to work with.\n\n`;
          explanation += `**Details:** ${inputText}\n\n`;
          explanation += `This information could come from the user, another function, or be initialized with a starting value.`;
        }
        break;
      
      case 'output':
        const outputText = node.text || node.label || '';
        explanation = `📤 **Displaying Result**\n\n`;
        
        // Analyze what's being output and connect to previous steps
        if (outputText.toLowerCase().includes('return')) {
          explanation += `**What's happening:** The function is sending back its result.\n\n`;
          explanation += `**Returning:** ${outputText}\n\n`;
          
          if (hasDecision) {
            explanation += `Based on the decision made earlier, the function now returns the appropriate value. `;
          }
          explanation += `When a function returns a value, it's like a calculator showing you the answer. This value can then be used by whatever called this function.`;
          
        } else if (outputText.toLowerCase().includes('print') || outputText.toLowerCase().includes('display')) {
          explanation += `**What's happening:** The program is showing information on the screen.\n\n`;
          explanation += `**Message:** ${outputText}\n\n`;
          
          // Check if this is after a decision
          if (hasDecision) {
            const codeLines = code.toLowerCase();
            
            if (outputText.toLowerCase().includes('even')) {
              explanation += `**Why "Even"?** Because in the previous decision step, the program checked if the number divides evenly by 2 (using num % 2 == 0). Since that condition was TRUE, we reached this step which prints "Even".\n\n`;
              explanation += `In other words: The number had **no remainder** when divided by 2, so it's an even number!`;
            } else if (outputText.toLowerCase().includes('odd')) {
              explanation += `**Why "Odd"?** Because in the previous decision step, the program checked if the number divides evenly by 2 (using num % 2 == 0). Since that condition was FALSE, we followed the "else" path which prints "Odd".\n\n`;
              explanation += `In other words: The number had a **remainder of 1** when divided by 2, so it's an odd number!`;
            } else {
              explanation += `This message appears based on the decision made in the previous step. The program followed one specific path through the code to reach here, and now it's showing you the result of that path.`;
            }
          } else if (hasInput) {
            explanation += `The program is displaying the result after processing the input it received earlier. This is how it communicates the final answer to you!`;
          } else {
            explanation += `This is how the program communicates results to you. Whatever appears here will be visible in the output.`;
          }
          
        } else if (outputText.toLowerCase().includes('write') || outputText.toLowerCase().includes('save')) {
          explanation += `**What's happening:** The program is saving data to a file or database.\n\n`;
          explanation += `**Action:** ${outputText}\n\n`;
          
          if (hasDecision || hasLoop) {
            explanation += `After processing the data through the previous steps (decisions and/or loops), the program now saves the results permanently. `;
          }
          explanation += `This stores the information so it can be used later, even after the program stops running.`;
          
        } else {
          explanation += `**What's happening:** The program is outputting information.\n\n`;
          explanation += `**Details:** ${outputText}\n\n`;
          
          if (hasDecision) {
            explanation += `This output is the result of the decision made earlier. Different paths lead to different outputs.\n\n`;
          }
          explanation += `This could be displayed to the user, sent to another system, or returned as a result.`;
        }
        break;
      
      case 'decision':
      case 'condition':
        const conditionText = node.text || node.label || '';
        explanation = `💎 **Decision Point**\n\n`;
        
        // Analyze the condition and provide context
        if (conditionText.includes('%') || conditionText.toLowerCase().includes('mod')) {
          explanation += `**What's being checked:** ${conditionText}\n\n`;
          
          if (hasInput) {
            explanation += `Remember the number we got as input earlier? Now we're checking if it's even or odd!\n\n`;
          }
          
          explanation += `The program is using the **modulo operator (%)** which gives you the remainder after division.\n\n`;
          explanation += `**How it works:**\n`;
          explanation += `• If we divide a number by 2 and get remainder 0 → It's EVEN\n`;
          explanation += `• If we divide a number by 2 and get remainder 1 → It's ODD\n\n`;
          explanation += `**Examples:**\n`;
          explanation += `• 10 ÷ 2 = 5 with remainder **0** → Even number\n`;
          explanation += `• 11 ÷ 2 = 5 with remainder **1** → Odd number\n\n`;
          explanation += `**Next steps:**\n`;
          explanation += `✅ **If TRUE (remainder is 0)** → Number is even, follow "Yes" path\n`;
          explanation += `❌ **If FALSE (remainder is not 0)** → Number is odd, follow "No" path`;
          
        } else if (conditionText.includes('>') || conditionText.includes('<') || conditionText.includes('greater') || conditionText.includes('less')) {
          explanation += `**What's being checked:** ${conditionText}\n\n`;
          
          if (hasInput) {
            explanation += `Using the value we received earlier, the program now compares it with another value.\n\n`;
          }
          
          explanation += `The program is comparing two values to see which one is bigger or smaller.\n\n`;
          explanation += `**Based on the comparison:**\n`;
          explanation += `✅ **If TRUE** → The condition is satisfied, follow the "Yes" path\n`;
          explanation += `❌ **If FALSE** → The condition is not satisfied, follow the "No" path`;
          
        } else if (conditionText.includes('==') || conditionText.toLowerCase().includes('equal')) {
          explanation += `**What's being checked:** ${conditionText}\n\n`;
          
          if (hasInput) {
            explanation += `The program is checking if the input value matches a specific condition.\n\n`;
          }
          
          explanation += `The program is checking if two things are exactly the same.\n\n`;
          explanation += `Think of it like checking if two puzzle pieces match:\n`;
          explanation += `✅ **If TRUE** → They match perfectly\n`;
          explanation += `❌ **If FALSE** → They're different`;
          
        } else if (conditionText.toLowerCase().includes('empty') || conditionText.toLowerCase().includes('null') || conditionText.toLowerCase().includes('none')) {
          explanation += `**What's being checked:** ${conditionText}\n\n`;
          explanation += `The program is checking if a variable has no value or is empty.\n\n`;
          explanation += `✅ **If TRUE** → The variable is empty/null\n`;
          explanation += `❌ **If FALSE** → The variable has a value`;
          
        } else {
          explanation += `**What's being checked:** ${conditionText}\n\n`;
          
          if (hasInput) {
            explanation += `Using the data received earlier, the program now makes a decision.\n\n`;
          }
          
          explanation += `The program asks a true/false question here. Based on the answer, it will take different paths through the code.\n\n`;
          explanation += `✅ **If TRUE** → follows one path\n`;
          explanation += `❌ **If FALSE** → follows a different path\n\n`;
          explanation += `This is like reaching a fork in the road and choosing which way to go based on a condition.`;
        }
        break;
      
      case 'loop':
        const loopText = node.text || node.label || '';
        explanation = `🔁 **Loop (Repeat Steps)**\n\n`;
        
        // Analyze the loop type
        if (loopText.toLowerCase().includes('for')) {
          explanation += `**Loop Type:** FOR loop\n**Condition:** ${loopText}\n\n`;
          explanation += `This is like counting: "Do this 10 times" or "Go through each item in the list."\n\n`;
          explanation += `The program will repeat the steps inside the loop a specific number of times. Each time through, it might use a different value (like counting 1, 2, 3, etc.).\n\n`;
          explanation += `When it finishes all the repetitions, it moves on to whatever comes next.`;
        } else if (loopText.toLowerCase().includes('while')) {
          explanation += `**Loop Type:** WHILE loop\n**Condition:** ${loopText}\n\n`;
          explanation += `This is like saying "Keep doing this until..."\n\n`;
          explanation += `Before each repetition, the program checks if the condition is still true. If yes, it does the loop again. If no, it stops and moves forward.\n\n`;
          explanation += `⚠️ Make sure the condition eventually becomes false, or the loop will run forever!`;
        } else if (loopText.toLowerCase().includes('each') || loopText.toLowerCase().includes('in')) {
          explanation += `**Loop Type:** FOR-EACH loop\n**Condition:** ${loopText}\n\n`;
          explanation += `This loop goes through each item in a collection one by one.\n\n`;
          explanation += `Think of it like looking at each photo in an album, or reading each name on a list. The loop automatically handles going from one item to the next until it's seen them all.`;
        } else {
          explanation += `**Condition:** ${loopText}\n\n`;
          explanation += `The program repeats the steps inside this loop multiple times.\n\n`;
          explanation += `It keeps checking the condition, and as long as it's true, it does another round. When the condition becomes false, it exits the loop and continues with the rest of the program.`;
        }
        break;
      
      case 'process':
      case 'rectangle':
        const text = (node.text || node.label || '').toLowerCase();
        const originalText = node.text || node.label || '';
        
        if (text.includes('calculate') || text.includes('compute') || text.includes('*') || text.includes('+') || text.includes('-') || text.includes('/')) {
          explanation = `⚙️ **Calculation**\n\n**What's happening:** ${originalText}\n\n`;
          explanation += `The program is doing some math here. It takes the values it has, performs the calculation, and stores the result in a variable.\n\n`;
          explanation += `For example, if you're calculating the area of a rectangle, it multiplies length × width and saves that number for later use.`;
        } else if (text.includes('assign') || text.includes('set') || text.includes('=') && !text.includes('==')) {
          explanation = `📝 **Saving Data**\n\n**What's happening:** ${originalText}\n\n`;
          explanation += `The program is storing a value in a variable (a named container for data).\n\n`;
          explanation += `Think of variables like labeled boxes. This step puts a value into the box so we can use it later. The label helps us find it when we need it!`;
        } else if (text.includes('call') || text.includes('function') || text.includes('()')) {
          explanation = `📞 **Calling Function**\n\n**What's happening:** ${originalText}\n\n`;
          explanation += `The program is running a separate piece of code (a function) and then coming back here.\n\n`;
          explanation += `Functions are like mini-programs that do specific tasks. Instead of writing the same code over and over, we can just call the function whenever we need it!`;
        } else if (text.includes('increment') || text.includes('++') || text.includes('+=')) {
          explanation = `📈 **Increasing Value**\n\n**What's happening:** ${originalText}\n\n`;
          explanation += `The program is adding to a variable's current value.\n\n`;
          explanation += `This is commonly used in loops to count iterations, or in calculations where you're accumulating a total.`;
        } else if (text.includes('append') || text.includes('push') || text.includes('add')) {
          explanation = `➕ **Adding to Collection**\n\n**What's happening:** ${originalText}\n\n`;
          explanation += `The program is adding a new item to a list or collection.\n\n`;
          explanation += `Think of it like adding a new contact to your phone, or putting a new item in your shopping cart.`;
        } else {
          explanation = `⚙️ **Processing Step**\n\n**What's happening:** ${originalText}\n\n`;
          explanation += `The program is performing this operation as part of accomplishing its overall task.\n\n`;
          explanation += `Each processing step brings us closer to the final result.`;
        }
        break;
      
      case 'function':
        explanation = `🔧 **Function**\n\n**Name:** ${node.text || node.label}\n\nThis is a reusable piece of code that can be called multiple times.`;
        break;
      
      default:
        explanation = `📋 **Step**\n\n${node.text || node.label}`;
        break;
    }
    
    // Add line number info
    if (node.lineNumber) {
      explanation += `\n\n📍 **Line ${node.lineNumber}** in your code`;
    }
    
    return explanation;
  };

  return (
    <main style={styles.container}>
      <div style={styles.splitContainer}>
        {/* Left side - Code Editor */}
        <section style={styles.leftPanel}>
          <div style={styles.controls}>
            <select 
              value={lang} 
              onChange={(e) => {
                const newLang = e.target.value;
                setLang(newLang);
                setCode(codeTemplates[newLang]);
              }} 
              style={styles.select}
            >
              <option value="python">Python</option>
              <option value="javascript">JavaScript</option>
              <option value="java">Java</option>
              <option value="c">C</option>
              <option value="cpp">C++</option>
              <option value="sql">SQL</option>
              <option value="html">HTML/CSS</option>
            </select>

            <button onClick={handleGenerate} style={styles.button}>
              Generate Flowchart
            </button>
          </div>

          <textarea
            ref={textareaRef}
            value={code}
            onChange={(e) => setCode(e.target.value)}
            style={styles.textarea}
            placeholder="Paste your code here..."
          />

          {message && <div style={styles.message}>{message}</div>}
        </section>

        {/* Right side - Flowchart */}
        <section style={styles.rightPanel}>
          <h3 style={styles.flowchartTitle}>Flowchart {selectedNode && "& Explanation"}</h3>
          <div style={styles.flowchartContainer}>
            {graph ? (
              <div style={{ 
                display: 'flex', 
                gap: '20px', 
                height: '100%', 
                width: '100%',
                minWidth: 0,
                overflow: 'hidden'
              }}>
                {/* Flowchart Section */}
                <div style={{ 
                  flex: selectedNode ? '0 0 50%' : '1', 
                  minHeight: 0,
                  minWidth: 0,
                  display: 'flex',
                  flexDirection: 'column',
                  border: '2px solid #e5e7eb',
                  borderRadius: '8px',
                  background: '#ffffff'
                }}>
                  <div style={{ 
                    flex: 1, 
                    overflow: 'auto',
                    padding: '10px'
                  }}>
                    <SvgFlow graph={graph} onNodeClick={handleNodeClick} />
                  </div>
                </div>
                
                {/* Explanation Panel */}
                {selectedNode && (
                  <div style={{
                    flex: '0 0 48%',
                    minWidth: 0,
                    background: '#ffffff',
                    border: '2px solid #e5e7eb',
                    borderRadius: '8px',
                    display: 'flex',
                    flexDirection: 'column',
                    boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
                    maxHeight: '100%'
                  }}>
                    <div style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center',
                      padding: '16px 20px',
                      borderBottom: '2px solid #e5e7eb',
                      flexShrink: 0,
                      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
                    }}>
                      <h4 style={{
                        margin: 0,
                        fontSize: '1.1rem',
                        fontWeight: 600,
                        color: '#ffffff'
                      }}>💡 Step Explanation</h4>
                      <button 
                        onClick={() => {
                          setSelectedNode(null);
                        }} 
                        style={{
                          background: 'rgba(255,255,255,0.2)',
                          color: '#ffffff',
                          border: 'none',
                          fontSize: '20px',
                          cursor: 'pointer',
                          padding: '4px 10px',
                          borderRadius: '6px',
                          fontWeight: 'bold',
                          transition: 'all 0.2s ease',
                          flexShrink: 0
                        }}
                        onMouseOver={(e) => e.target.style.background = 'rgba(255,255,255,0.3)'}
                        onMouseOut={(e) => e.target.style.background = 'rgba(255,255,255,0.2)'}
                      >
                        ✕
                      </button>
                    </div>
                    <div style={{
                      flex: 1,
                      minHeight: 0,
                      overflow: 'auto',
                      background: '#f9fafb',
                      padding: '20px'
                    }}>
                      {getNodeExplanation(selectedNode).split('\n\n').map((paragraph, idx) => (
                        <div key={idx} style={{
                          marginBottom: '16px',
                          fontSize: '0.95rem',
                          lineHeight: 1.7,
                          color: '#374151'
                        }}>
                          {paragraph.split('**').map((part, i) => 
                            i % 2 === 1 ? (
                              <strong key={i} style={{ color: '#667eea', fontWeight: '600' }}>{part}</strong>
                            ) : (
                              <span key={i}>{part}</span>
                            )
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div style={styles.placeholder}>
                No flowchart yet — click "Generate Flowchart"
              </div>
            )}
          </div>
        </section>
      </div>
    </main>
  );
}

const styles = {
  container: {
    maxWidth: '100%',
    margin: '24px auto',
    padding: '0 24px',
    height: 'calc(100vh - 100px)'
  },
  splitContainer: {
    display: 'flex',
    gap: 20,
    height: '100%'
  },
  leftPanel: {
    flex: '0 0 32%',
    background: '#fff',
    padding: 20,
    borderRadius: 12,
    boxShadow: '0 6px 18px rgba(2,6,23,0.06)',
    display: 'flex',
    flexDirection: 'column',
    overflow: 'hidden'
  },
  rightPanel: {
    flex: '1',
    background: '#fff',
    padding: 20,
    borderRadius: 12,
    boxShadow: '0 6px 18px rgba(2,6,23,0.06)',
    display: 'flex',
    flexDirection: 'column',
    overflow: 'hidden',
    minWidth: 0
  },
  controls: {
    display: 'flex',
    gap: 12,
    alignItems: 'center',
    marginBottom: 12,
    flexShrink: 0
  },
  select: {
    padding: '8px 10px',
    borderRadius: 8,
    border: '1px solid #e6e9ef',
    fontSize: 14,
    cursor: 'pointer'
  },
  button: {
    padding: '8px 14px',
    background: '#4b0082',
    color: '#fff',
    border: 'none',
    borderRadius: 8,
    cursor: 'pointer',
    transition: 'all .2s ease',
    boxShadow: '0 6px 12px rgba(75,0,130,0.08)',
    fontSize: 14,
    fontWeight: 600
  },
  textarea: {
    width: '100%',
    flex: 1,
    padding: 12,
    borderRadius: 10,
    border: '1px solid #e6e9ef',
    fontFamily: 'monospace',
    fontSize: 13,
    resize: 'none',
    outline: 'none',
    transition: 'border-color .2s ease'
  },
  flowchartTitle: {
    margin: '0 0 16px 0',
    fontSize: 18,
    fontWeight: 600,
    color: '#1f2937',
    flexShrink: 0
  },
  flowchartContainer: {
    flex: 1,
    minHeight: 0,
    display: 'flex',
    flexDirection: 'column'
  },
  message: {
    marginTop: 10,
    padding: '12px 16px',
    borderRadius: 8,
    backgroundColor: '#fee2e2',
    color: '#991b1b',
    border: '1px solid #fca5a5',
    fontSize: '14px',
    fontWeight: '500',
    flexShrink: 0
  },
  placeholder: {
    color: '#9ca3af',
    padding: 40,
    textAlign: 'center',
    fontSize: 15
  },
  explanationPanel: {
    flex: '0 0 38%',
    background: '#f8fafc',
    border: '2px solid #e2e8f0',
    borderRadius: 12,
    padding: 16,
    display: 'flex',
    flexDirection: 'column',
    overflow: 'hidden',
    boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
    animation: 'slideIn 0.3s ease'
  },
  explanationHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 12,
    paddingBottom: 12,
    borderBottom: '2px solid #e2e8f0'
  },
  explanationTitle: {
    margin: 0,
    fontSize: 16,
    fontWeight: 700,
    color: '#1f2937'
  },
  closeButton: {
    background: 'transparent',
    border: 'none',
    fontSize: 20,
    color: '#6b7280',
    cursor: 'pointer',
    padding: '4px 8px',
    borderRadius: 4,
    transition: 'all 0.2s ease',
    fontWeight: 'bold'
  },
  explanationContent: {
    flex: 1,
    overflowY: 'auto',
    paddingRight: 8
  },
  explanationText: {
    margin: '0 0 12px 0',
    fontSize: 14,
    lineHeight: 1.6,
    color: '#374151',
    whiteSpace: 'pre-wrap'
  }
};

export default Editor;
